-- =============================================================================
-- 0044_why_we_do_it.sql
--
-- GENERATED by scripts/build-why-we-do-it.mjs. Do not hand-edit.
--
-- The app has explained every STEP since 0014 and has never explained the RITE.
-- A reader could learn why the seat is consecrated before you sit on it and
-- still not know why anyone keeps the Varalakshmi vratham. The step philosophy
-- is the close reading; this is what you would say if someone asked at the door.
--
-- Written FROM the books rather than copied off them -- the English in all three
-- is the editor's. Varalakshmi from book pp.110-112, Ganesha from p.52, the
-- daily rite from p.27 and its placement verse.
--
-- The four PLANNED nitya karmas are deliberately absent. They have no steps, no
-- preparation screen and nowhere to show this, and writing it before the rite is
-- transcribed would be writing about a book nobody has read yet.
-- =============================================================================

begin;

alter table public.poojas
  add column if not exists why_en text,
  add column if not exists why_ta text;

comment on column public.poojas.why_en is
  'Four to seven sentences on why the rite is kept at all: purpose, the idea behind its shape, and what it is for. Pooja-level, distinct from pooja_steps.philosophy_en which explains one step.';

update public.poojas set
       why_en     = 'Ganesha is Adipujya, the first to be worshipped, and the book is careful to say the position was given to him by the other deities rather than taken. So a Ganesha pooja is what you do before the thing you actually came to do: before a vratham, before a journey, before anything begun for the first time. He removes obstacles, and the older texts are equally clear that he places them, which is why the rite asks rather than instructs. Most households invoke him not in a bronze but in a cone of turmeric paste made that morning — the same substance Parvati is said to have fashioned him from — and send him off again at the end. Nothing is kept. What is asked for is a clear road, not a favour.',
       why_ta     = 'கணபதி ஆதிபூஜ்யர் — முதலில் வணங்கப்பட வேண்டியவர். அந்த இடத்தை அவர் பிடித்துக் கொள்ளவில்லை, மற்ற தேவர்களே ஒருமித்து அளித்தனர் என்பதை நூல் தெளிவாகச் சொல்கிறது. எனவே எந்த ஒரு முக்கியமான செயலுக்கும் — விரதம், பயணம், புதிய தொடக்கம் — அதற்கு முன் செய்யப்படுவது இந்தப் பூஜை. விக்னங்களை நீக்குபவர் அவரே; அவற்றை வைப்பவரும் அவரே என்பதால், இந்த வழிபாடு கட்டளையிடுவதில்லை, வேண்டுகிறது. பெரும்பாலான வீடுகளில் அன்றைக்கே பிசைந்த மஞ்சள் பிள்ளையாரில் ஆவாஹனம் செய்து, இறுதியில் உத்வாசனம் செய்து விடுகிறார்கள். எதுவும் வைத்துக்கொள்ளப்படுவதில்லை. கேட்கப்படுவது வரம் அல்ல — தடையற்ற வழி.',
       updated_at = now()
 where id = 'ganesha_standard';

update public.poojas set
       why_en     = 'The Rigveda uses one word, Sri, for the things a life needs to go well: enough food, a steady mind, a house worth living in, and standing among the people around you. Lakshmi is that word personified, which is why this vratham is a household observance rather than a temple one — it is kept for the house, by the women of the house, who the book says are looked upon as Lakshmi already. It falls on the Friday before the Shravana full moon. The goddess is invited into a kalasham dressed as her, worshipped through the day, and a nine-knotted turmeric thread is tied on the wrist so that the vow is something you can see. The stories the book tells to explain it — Charumati, and Shyama Bala whose mother insulted an old woman at the door — all turn on the same point: prosperity arrives where it is treated as a guest rather than a possession.',
       why_ta     = 'நல்ல வாழ்க்கைக்குத் தேவையான அனைத்தையும் — உணவு, மன நிறைவு, வாழத் தகுந்த இல்லம், சமூகத்தில் மதிப்பு — ரிக் வேதம் "ஸ்ரீ" என்ற ஒரே சொல்லால் குறிக்கிறது. அந்தச் சொல்லின் உருவமே லக்ஷ்மி. அதனால்தான் இது கோயில் வழிபாடு அல்ல, இல்லத்து விரதம் — வீட்டுக்காக, வீட்டுப் பெண்களால் அனுஷ்டிக்கப்படுவது; அவர்களே லக்ஷ்மியின் வடிவம் என்று நூல் கூறுகிறது. ஶ்ராவண பௌர்ணமிக்கு முந்தைய வெள்ளிக்கிழமை இது கொண்டாடப்படுகிறது. தாயாரை அலங்கரித்த கலசத்தில் ஆவாஹனம் செய்து நாள் முழுவதும் வழிபட்டு, ஒன்பது முடிச்சுகளிட்ட மஞ்சள் நோன்புக் கயிறு கையில் கட்டப்படுகிறது — விரதம் கண்ணுக்குத் தெரியும் வகையில். சாருமதி, ஶ்யாமபாலா ஆகியோரின் கதைகள் ஒரே கருத்தைச் சொல்கின்றன: செல்வத்தை உடைமையாக அல்ல, விருந்தாளியாக நடத்தும் இடத்திலேயே அது தங்குகிறது.',
       updated_at = now()
 where id = 'varalakshmi_vratham';

update public.poojas set
       why_en     = 'This is the rite of an ordinary morning, and its shape is an argument. Instead of one god it worships five — Shiva at the centre, Vishnu to the north-east, Surya to the south-east, Vinayaka to the south-west and Devi to the north-west — and the household puts its own chosen deity in the middle, so the arrangement holds whichever that is. That is the Smartha answer to sectarian quarrel: none of the five outranks the others, and the one you love most is placed at the centre without the other four being demoted. It has no date because it has no occasion; the occasion is that it is morning. What it is for is not a request at all — it is the household beginning its day at its own altar rather than at its own business.',
       why_ta     = 'இது ஒரு சாதாரண காலைப் பொழுதின் வழிபாடு; ஆனால் அதன் அமைப்பே ஒரு கருத்தைச் சொல்கிறது. ஒரு தெய்வம் அல்ல, ஐந்து தெய்வங்கள் — நடுவில் சிவன், ஈஶான்யத்தில் விஷ்ணு, ஆக்னேயத்தில் சூரியன், நைருதியில் விநாயகர், வாயுவ்யத்தில் தேவி. வீட்டாரின் இஷ்ட தெய்வம் எதுவோ அதுவே நடுவில் வைக்கப்படும்; அமைப்பு மாறுவதில்லை. மத வேறுபாடுகளுக்கு ஸ்மார்த்த மரபு தரும் பதில் இதுதான் — ஐவரில் எவரும் உயர்ந்தவர் அல்ல, நமக்குப் பிடித்தவரை நடுவில் வைத்தாலும் மற்ற நால்வரும் தாழ்த்தப்படுவதில்லை. இதற்குத் திதியோ நாளோ இல்லை; காலை விடிந்ததே காரணம். இது ஏதோ ஒன்றைக் கேட்பதற்கானது அல்ல — நாளை வியாபாரத்தில் அல்ல, வீட்டுப் பூஜையறையில் தொடங்குவதற்கானது.',
       updated_at = now()
 where id = 'nitya_panchayatana';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- Every PUBLISHED pooja has both. Planned ones must not: nothing shows it.
  select count(*) into n from public.poojas
   where status = 'published'
     and (coalesce(trim(why_en), '') = '' or coalesce(trim(why_ta), '') = '');
  if n <> 0 then raise exception '% published pooja(s) have no why text', n; end if;

  select count(*) into n from public.poojas
   where status = 'planned' and coalesce(trim(why_en), '') <> '';
  if n <> 0 then raise exception '% planned pooja(s) carry why text with nowhere to show it', n; end if;

  -- No two rites share it. One template filled three times is how the five
  -- nitya archanas ended up with one paragraph between them; see 0040.
  select count(distinct why_en) into n from public.poojas where why_en is not null;
  if n <> 3 then raise exception 'the why texts are not distinct: % of 3', n; end if;

  -- Tamil is Tamil, and English is not Devanagari.
  select count(*) into n from public.poojas where why_ta is not null and why_ta !~ '[஀-௿]';
  if n <> 0 then raise exception '% why_ta value(s) carry no Tamil', n; end if;
  select count(*) into n from public.poojas where why_en ~ '[ऀ-ॿ]';
  if n <> 0 then raise exception '% why_en value(s) carry Devanagari', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
